-- mod-city-bots — stage cast characters (GUIDs 9000001-9000400), consolidated seed.
--
-- Self-contained on purpose: this file only touches acore_characters. It does
-- not read acore_playerbots.citizen_roster or acore_world.city_bot_poi, so the
-- AzerothCore database updater can apply it on a fresh install in its normal
-- order (auth -> characters -> world) before those tables exist.
--
-- It replaces the former db-characters update chain (2026_07_15_02 through
-- 2026_08_11_01) with the final state that chain produced; the individual
-- repair steps are in git history. Identity (account, name, race, class,
-- gender, level) matches playerbots update 2026_07_15_00_citizen_roster.sql.
-- Account = 12001 + (guid - 9000001); password citybot_stage (see db-auth).
--
-- Reapplying this file re-seeds the 400 stage-cast characters and their
-- homebinds (positions, at_login, equipmentCache, ...) back to the shipped state.

-- Legacy one-size weapon seed (item GUIDs 910000000-910009999): remove.
DELETE FROM `mail_items`         WHERE `item_guid` >= 910000000 AND `item_guid` < 910010000;
DELETE FROM `character_inventory` WHERE `item`     >= 910000000 AND `item`      < 910010000;
DELETE FROM `item_instance`      WHERE `guid`      >= 910000000 AND `guid`      < 910010000;

-- Persisted playerbot randomizer side effects (pets, auras): remove. The
-- module drives these bots directly.
DELETE `psc` FROM `pet_spell_cooldown` `psc`
  JOIN `character_pet` `cp` ON `cp`.`id` = `psc`.`guid`
 WHERE `cp`.`owner` BETWEEN 9000001 AND 9000400;
DELETE `ps` FROM `pet_spell` `ps`
  JOIN `character_pet` `cp` ON `cp`.`id` = `ps`.`guid`
 WHERE `cp`.`owner` BETWEEN 9000001 AND 9000400;
DELETE `pa` FROM `pet_aura` `pa`
  JOIN `character_pet` `cp` ON `cp`.`id` = `pa`.`guid`
 WHERE `cp`.`owner` BETWEEN 9000001 AND 9000400;
DELETE FROM `character_pet_declinedname` WHERE `owner` BETWEEN 9000001 AND 9000400;
DELETE FROM `character_pet`              WHERE `owner` BETWEEN 9000001 AND 9000400;
DELETE FROM `character_aura`             WHERE `guid`  BETWEEN 9000001 AND 9000400;

-- Stage cast characters.
DELETE FROM `character_homebind` WHERE `guid` BETWEEN 9000001 AND 9000400;
DELETE FROM `characters`         WHERE `guid` BETWEEN 9000001 AND 9000400;









-- Homebind = spawn position (Player::LoadFromDB hard-fails without a row).







